function mergeWithDefaults(saved) {
  const defaults = window.SITE_DEFAULTS;
  if (!saved) return JSON.parse(JSON.stringify(defaults));
  const out = JSON.parse(JSON.stringify(defaults));
  for (const k of Object.keys(saved)) {
    if (Array.isArray(saved[k]) && Array.isArray(defaults[k])) {
      out[k] = saved[k].map((item, i) => Object.assign({}, defaults[k][i] || {}, item));
    } else if (Array.isArray(saved[k])) {
      out[k] = saved[k];
    } else if (typeof saved[k] === 'object' && saved[k] !== null) {
      out[k] = Object.assign({}, out[k], saved[k]);
    } else {
      out[k] = saved[k];
    }
  }
  return out;
}
window.mergeWithDefaults = mergeWithDefaults;

/* Synchronous: returns defaults merged with localStorage (admin preview only). */
window.loadSiteContent = function () {
  let saved = null;
  try { saved = JSON.parse(localStorage.getItem('siteContent') || 'null'); } catch (e) {}
  return mergeWithDefaults(saved);
};

/* Remote loading is disabled — defaults above are the source of truth. */
window.loadSiteContentRemote = async function () { return null; };
